#include "icu_locale_manifest.h" // generated by the reduced-data step
#include "icu_runtime.hpp"

#include <cstdint>

#include <unicode/udata.h>
#include <unicode/ures.h>
#include <unicode/utypes.h>
#include <unicode/uversion.h>

// The genccode object defines the blob under the pinned ICU data symbol (TESSERA_ICU_DATA_SYMBOL
// comes from the tessera_icu INTERFACE target, so the name follows the ICU version). The
// declaration must stay at namespace scope: inside an anonymous namespace it would take internal
// linkage, so on a C++ compiler that keeps the C name only for external declarations (GCC) the
// reference resolves to an undefined `(anonymous namespace)::icudt<major>_dat` instead of the C
// symbol the generated object defines.
extern "C" {
extern const char TESSERA_ICU_DATA_SYMBOL[];
}

namespace tessera::ui::text::icu {
namespace {

bool attempted = false;
bool installed = false;
std::string last_error;
std::string runtime_version;

void record_failure(std::string_view what, UErrorCode status) {
    last_error.assign(what);
    if (U_FAILURE(status)) {
        last_error.append(": ");
        last_error.append(u_errorName(status));
    }
}

} // namespace

InitStatus initialize() {
    if (attempted) {
        return installed ? InitStatus::AlreadyReady : InitStatus::Failed;
    }
    attempted = true;

    UVersionInfo version{};
    u_getVersion(version);
    if (version[0] != TESSERA_ICU_VERSION_MAJOR) {
        last_error = "ICU version mismatch: linked library is ";
        last_error.append(std::to_string(static_cast<int>(version[0])));
        last_error.append(".");
        last_error.append(std::to_string(static_cast<int>(version[1])));
        last_error.append(", pinned data is ");
        last_error.append(kIcuVersion);
        return InitStatus::Failed;
    }
    runtime_version = std::to_string(static_cast<int>(version[0])) + "." +
                      std::to_string(static_cast<int>(version[1])) + "." +
                      std::to_string(static_cast<int>(version[2]));

    UErrorCode status = U_ZERO_ERROR;
    udata_setCommonData(TESSERA_ICU_DATA_SYMBOL, &status);
    if (U_FAILURE(status)) {
        record_failure("ICU rejected the linked data blob", status);
        return InitStatus::Failed;
    }

    // Installing a package is not proof it is readable: open the root bundle, which the reduced
    // step always keeps. A failure here means the blob and U_ICUDATA_NAME disagree.
    status = U_ZERO_ERROR;
    UResourceBundle* root = ures_open(nullptr, "root", &status);
    const bool readable = U_SUCCESS(status) && root != nullptr;
    if (root != nullptr) {
        ures_close(root);
    }
    if (!readable) {
        record_failure("ICU cannot read its root locale bundle", status);
        return InitStatus::Failed;
    }

    installed = true;
    last_error.clear();
    return InitStatus::Ok;
}

bool ready() {
    return installed;
}

std::string_view init_error() {
    return last_error;
}

std::string_view library_version() {
    return runtime_version;
}

std::string_view package_name() {
    return installed ? std::string_view(U_ICUDATA_NAME) : std::string_view();
}

BlobInfo blob_info() {
    return BlobInfo{std::string_view(kDataName),
                    std::string_view(kIcuVersion),
                    std::string_view(kBlobSha256),
                    kBlobBytes,
                    kBlobItems,
                    kKeptLocaleCount};
}

} // namespace tessera::ui::text::icu
